//! Unicode character names, as Python 3.11's `unicodedata.name` (Unicode 14.0)
//! reports them, so the `git.ascii` hook names each refused character.
//!
//! `unicode_names.txt` lists every named code point above U+007F except the
//! algorithmic ones below, sorted, front-coded one per line:
//! `<hex delta from previous code point> <bytes shared with previous name> <rest of name>`
//! (the first delta is from U+007F). It was generated by enumerating
//! `unicodedata.name(chr(cp))` for all code points.

use std::sync::OnceLock;

const TABLE: &str = include_str!("unicode_names.txt");

/// Ranges whose names are `<prefix><code point in hex>`.
const RANGES: &[(u32, u32, &str)] = &[
    (0x3400, 0x4DBF, "CJK UNIFIED IDEOGRAPH-"),
    (0x4E00, 0x9FFF, "CJK UNIFIED IDEOGRAPH-"),
    (0xF900, 0xFA6D, "CJK COMPATIBILITY IDEOGRAPH-"),
    (0xFA70, 0xFAD9, "CJK COMPATIBILITY IDEOGRAPH-"),
    (0x18B00, 0x18CD5, "KHITAN SMALL SCRIPT CHARACTER-"),
    (0x1B170, 0x1B2FB, "NUSHU CHARACTER-"),
    (0x20000, 0x2A6DF, "CJK UNIFIED IDEOGRAPH-"),
    (0x2A700, 0x2B738, "CJK UNIFIED IDEOGRAPH-"),
    (0x2B740, 0x2B81D, "CJK UNIFIED IDEOGRAPH-"),
    (0x2B820, 0x2CEA1, "CJK UNIFIED IDEOGRAPH-"),
    (0x2CEB0, 0x2EBE0, "CJK UNIFIED IDEOGRAPH-"),
    (0x2F800, 0x2FA1D, "CJK COMPATIBILITY IDEOGRAPH-"),
    (0x30000, 0x3134A, "CJK UNIFIED IDEOGRAPH-"),
];

// Hangul syllables (Unicode ch. 3.12).
const S_BASE: u32 = 0xAC00;
const S_COUNT: u32 = 11172;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = 588;
const JAMO_L: [&str; 19] = [
    "G", "GG", "N", "D", "DD", "R", "M", "B", "BB", "S", "SS", "", "J", "JJ", "C", "K", "T", "P",
    "H",
];
const JAMO_V: [&str; 21] = [
    "A", "AE", "YA", "YAE", "EO", "E", "YEO", "YE", "O", "WA", "WAE", "OE", "YO", "U", "WEO", "WE",
    "WI", "YU", "EU", "YI", "I",
];
const JAMO_T: [&str; 28] = [
    "", "G", "GG", "GS", "N", "NJ", "NH", "D", "L", "LG", "LM", "LB", "LS", "LT", "LP", "LH", "M",
    "B", "BS", "S", "SS", "NG", "J", "C", "K", "T", "P", "H",
];

fn table() -> &'static [(u32, Box<str>)] {
    static NAMES: OnceLock<Vec<(u32, Box<str>)>> = OnceLock::new();
    NAMES.get_or_init(|| {
        let mut v = Vec::with_capacity(33_000);
        let (mut cp, mut prev) = (0x7Fu32, String::new());
        for line in TABLE.lines() {
            let mut parts = line.splitn(3, ' ');
            let delta = u32::from_str_radix(parts.next().unwrap_or(""), 16).expect("table delta");
            let shared: usize = parts.next().unwrap_or("").parse().expect("table prefix");
            cp += delta;
            prev.truncate(shared);
            prev.push_str(parts.next().unwrap_or(""));
            v.push((cp, prev.clone().into_boxed_str()));
        }
        v
    })
}

/// `unicodedata.name(c)`, or None if the character has no name.
pub fn name(c: char) -> Option<String> {
    let cp = c as u32;
    if (S_BASE..S_BASE + S_COUNT).contains(&cp) {
        let s = cp - S_BASE;
        return Some(format!(
            "HANGUL SYLLABLE {}{}{}",
            JAMO_L[(s / N_COUNT) as usize],
            JAMO_V[(s % N_COUNT / T_COUNT) as usize],
            JAMO_T[(s % T_COUNT) as usize]
        ));
    }
    if let Some((_, _, prefix)) = RANGES.iter().find(|(lo, hi, _)| (*lo..=*hi).contains(&cp)) {
        return Some(format!("{prefix}{cp:X}"));
    }
    let t = table();
    t.binary_search_by_key(&cp, |e| e.0)
        .ok()
        .map(|i| t[i].1.to_string())
}

#[cfg(test)]
mod tests {
    use super::name;

    #[test]
    fn known_names() {
        for (c, n) in [
            ('\u{A0}', "NO-BREAK SPACE"),
            ('\u{2212}', "MINUS SIGN"),
            ('\u{201C}', "LEFT DOUBLE QUOTATION MARK"),
            ('é', "LATIN SMALL LETTER E WITH ACUTE"),
            ('\u{4E2D}', "CJK UNIFIED IDEOGRAPH-4E2D"),
            ('\u{AC00}', "HANGUL SYLLABLE GA"),
            ('\u{D7A3}', "HANGUL SYLLABLE HIH"),
            ('\u{1F600}', "GRINNING FACE"),
            ('\u{E0001}', "LANGUAGE TAG"),
        ] {
            assert_eq!(name(c).as_deref(), Some(n), "{c:?}");
        }
        assert_eq!(name('\u{E000}'), None); // private use
        assert_eq!(name('\u{0378}'), None); // unassigned
    }
}
